INSERT INTO score_components (id, score_id, code, name, description) VALUES ('d38d4cd4-8532-5dd3-97d6-a1225cb9f58b', '23342ee8-1cce-5504-99ae-f93e4d69971d', 'incentive_dependence', 'Incentive dependence', 'Share of activity attributable to token incentives. No reliable Phase 1 source.');
INSERT INTO score_components (id, score_id, code, name, description) VALUES ('2ea1b1ad-7914-56dc-8146-c866a1a9d7de', '23342ee8-1cce-5504-99ae-f93e4d69971d', 'necessity_inverse', 'Token-necessity inverse', '10 minus analyst-assessed Token Necessity. A token the protocol does not need is a reflexive-asset warning sign.');
INSERT INTO score_components (id, score_id, code, name, description) VALUES ('abb1803b-3aa4-5b11-849b-06980cfef512', '23342ee8-1cce-5504-99ae-f93e4d69971d', 'supply_overhang', 'Supply overhang', 'Share of fully-diluted value not yet circulating: (FDV - market cap) / FDV * 10. Future dilution is future sell pressure.');
